"use client";

// src/app/casino/hillstrike/play-ai/PageClient.tsx
//
// Hillstrike — free practice against the bot.
//
// There is no match row, no wager and no rating here: the whole match lives in
// one React state value shaped by `src/lib/hillstrike/rules.ts`, the battlefield
// is generated by `src/lib/hillstrike/generation.ts`, the bot is a pure function
// of that same state (`src/lib/hillstrike/ai.ts`) and the match clock is this
// page's own ("time is up" is a local call to the engine's `finishOnTime`, which
// owns the verdict: more HP wins, level HP draws).
//
// THE UI OWNS NO RULES. It sends the engine one of its two actions (shoot or
// drive) and renders what comes back: the resolved trajectory, both HP pools, the
// turn, the action counter, the crater, the collapse and the drive. A drag is
// converted by `aimFromDrag`, a preview is a real `simulateShot` of the pending
// aim, and an action is applied with `applyAction` — the same functions the
// online store uses.
//
// THE BOARD FILLS THE SCREEN. The battlefield is the frame, and the control bar
// is mounted INSIDE it at the bottom, so Fire and both drives are always in
// reach without scrolling. Everything optional (bot difficulty, the rules) sits
// below the frame.
//
// A practice match is deliberately client-side: it cannot fail because a
// socket, a database or a second human is unavailable, and it stays unrated by
// construction (it never talks to an API).
//
// `?seed=<uint32>` pins the FIRST layout (handy for reproducing a bug or a
// browser test); Restart always deals a fresh random layout.

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";

import NavigationBar from "../../../../components/navigation-bar";
import PvpResultScreen from "../../../../components/result/PvpResultScreen";
import AiDifficultyPicker from "../../../../components/lobby/AiDifficultyPicker";
import HillstrikeBattlefield, {
  type HillstrikeAnimation,
  type HillstrikePreview,
} from "../../../../components/hillstrike/HillstrikeBattlefield";
import HillstrikeHud from "../../../../components/hillstrike/HillstrikeHud";
import {
  HILLSTRIKE_TIER_HINTS,
  chooseAiAction,
} from "../../../../lib/hillstrike/ai";
import {
  DEFAULT_MATCH_DURATION_MS,
  MATCH_DURATION_OPTIONS_MS,
  MAX_HP,
  MOVE_RANGE,
  TICK_MS,
} from "../../../../lib/hillstrike/constants";
import { simulateShot } from "../../../../lib/hillstrike/physics";
import {
  applyAction,
  createInitialState,
  finishOnTime,
  hpOf,
  validateAction,
} from "../../../../lib/hillstrike/rules";
import { readStoredAiDifficulty, type AiDifficulty } from "../../../../lib/aiDifficulty";
import type {
  ActionVerdict,
  HillstrikeAction,
  HillstrikeState,
  MoveDirection,
  Seat,
  ShotInput,
} from "../../../../lib/hillstrike/types";

const HUMAN_SEAT: Seat = "player1";
const AI_SEAT: Seat = "player2";
const AI_THINK_DELAY_MS = 650;
/** How long the post-impact collapse/feedback plays before input returns. */
const SETTLE_MS = 340;
const LOBBY_PATH = "/casino";
const MAX_SEED = 0xffffffff;

/** A fresh battlefield seed from the browser's CSPRNG (never a repeated layout). */
function drawSeed(): number {
  if (typeof crypto !== "undefined" && typeof crypto.getRandomValues === "function") {
    const buffer = new Uint32Array(1);
    crypto.getRandomValues(buffer);
    return buffer[0];
  }
  return Math.floor(Math.random() * (MAX_SEED + 1)) >>> 0;
}

/** The `?seed=` override, when it is a valid 32-bit integer. */
function seedFromLocation(): number | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = new URLSearchParams(window.location.search).get("seed");
    if (raw === null || raw.trim() === "") return null;
    const parsed = Number(raw);
    return Number.isInteger(parsed) && parsed >= 0 && parsed <= MAX_SEED ? parsed : null;
  } catch {
    return null;
  }
}

/** Flight time for a resolved shot, bounded so a lob never stalls the match. */
function flightDuration(impactTick: number): number {
  return Math.max(220, Math.min(1400, Math.round(impactTick * TICK_MS)));
}

export default function HillstrikePracticePage() {
  const router = useRouter();

  // `null` during the first client frame: a battlefield seed must be drawn in
  // the browser (the server has no per-match seed to render), so the page shows
  // a preparing state instead of rendering a layout it would immediately replace.
  const [match, setMatch] = useState<HillstrikeState | null>(null);
  const matchRef = useRef<HillstrikeState | null>(null);

  const [difficulty, setDifficulty] = useState<AiDifficulty>("normal");
  const [aim, setAim] = useState<ShotInput | null>(null);
  const [animation, setAnimation] = useState<HillstrikeAnimation | null>(null);
  const [resolving, setResolving] = useState(false);
  const [aiThinking, setAiThinking] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);
  const [session, setSession] = useState({ wins: 0, losses: 0 });

  // ── The match clock ────────────────────────────────────────────────────
  // Chess clocks, chosen before (or during) a match: 5, 10 or 15 minutes. The
  // engine never reads a clock, so this page holds the deadline and hands the
  // engine a pure `finishOnTime` when it passes.
  const [durationMs, setDurationMs] = useState<number>(DEFAULT_MATCH_DURATION_MS);
  const [endsAt, setEndsAt] = useState<number | null>(null);
  const [clockMs, setClockMs] = useState<number>(DEFAULT_MATCH_DURATION_MS);
  const durationRef = useRef<number>(DEFAULT_MATCH_DURATION_MS);
  const startedAtRef = useRef<number>(0);

  const busyRef = useRef(false);
  const timersRef = useRef<number[]>([]);
  const countedMatchRef = useRef<string | null>(null);

  const clearTimers = useCallback(() => {
    for (const timer of timersRef.current) window.clearTimeout(timer);
    timersRef.current = [];
  }, []);

  const installMatch = useCallback((next: HillstrikeState) => {
    matchRef.current = next;
    setMatch(next);
  }, []);

  const startFresh = useCallback(
    (seed: number) => {
      clearTimers();
      busyRef.current = false;
      countedMatchRef.current = null;
      setAim(null);
      setAnimation(null);
      setResolving(false);
      setAiThinking(false);
      setNotice(null);
      const startedAt = Date.now();
      startedAtRef.current = startedAt;
      setEndsAt(startedAt + durationRef.current);
      setClockMs(durationRef.current);
      installMatch(createInitialState({ seed }));
    },
    [clearTimers, installMatch],
  );

  const restart = useCallback(() => {
    startFresh(drawSeed());
  }, [startFresh]);

  // Boot once, in the browser: the pinned seed if one was supplied, else a fresh
  // random layout. The stored bot tier is read here too (localStorage only
  // exists on the client).
  const bootedRef = useRef(false);
  useEffect(() => {
    if (bootedRef.current) return;
    bootedRef.current = true;
    setDifficulty(readStoredAiDifficulty("hillstrike"));
    startFresh(seedFromLocation() ?? drawSeed());
    return () => clearTimers();
  }, [clearTimers, startFresh]);

  // The clock ticks while a live match exists.
  useEffect(() => {
    if (endsAt === null) return undefined;
    const tick = () => setClockMs(Math.max(0, endsAt - Date.now()));
    tick();
    const id = window.setInterval(tick, 250);
    return () => window.clearInterval(id);
  }, [endsAt]);

  // Time up: the engine decides (more HP wins, level HP draws). Held back while
  // an action is still landing, so the last shot always counts.
  useEffect(() => {
    if (!match || match.status !== "playing" || resolving) return;
    if (clockMs > 0) return;
    setEndsAt(null);
    setAim(null);
    installMatch(finishOnTime(match).state);
  }, [clockMs, installMatch, match, resolving]);

  /**
   * Change the clock. Mid-match it moves the deadline rather than restarting, so
   * tapping a duration never throws away the position you are playing.
   */
  const changeDuration = useCallback((next: number) => {
    if (!(MATCH_DURATION_OPTIONS_MS as readonly number[]).includes(next)) return;
    durationRef.current = next;
    setDurationMs(next);
    const live = matchRef.current;
    if (!live || live.status !== "playing") return;
    const deadline = startedAtRef.current + next;
    setEndsAt(deadline);
    setClockMs(Math.max(0, deadline - Date.now()));
  }, []);

  const canPlay = Boolean(
    match &&
      match.status === "playing" &&
      !resolving &&
      !aiThinking &&
      match.turn === HUMAN_SEAT,
  );

  // The preview is the ENGINE's own resolution of the pending aim, so what the
  // dotted line shows is exactly what the shot will do.
  const preview = useMemo<HillstrikePreview | null>(() => {
    if (!match || !aim || !canPlay) return null;
    try {
      const simulation = simulateShot({
        battlefield: match.battlefield,
        shooterSeat: HUMAN_SEAT,
        shot: aim,
        projectile: match.projectile,
      });
      return { path: simulation.path, impact: simulation.impact };
    } catch {
      return null;
    }
  }, [aim, canPlay, match]);

  /**
   * Resolve one action and play it.
   *
   * The authoritative state is installed when the projectile LANDS, so HP, the
   * action counter and the turn change at the moment of impact. A drive installs
   * immediately and plays its short settle tween, because there is no flight to
   * wait for.
   */
  const playAction = useCallback(
    (seat: Seat, action: HillstrikeAction) => {
      const current = matchRef.current;
      if (!current || busyRef.current) return;

      const verdict = validateAction(current, seat, action);
      if (!verdict.ok) {
        // `strict` is off in this repo, so the union is not narrowed by the
        // boolean check; the cast keeps the engine's own wording type-safe.
        setNotice((verdict as Extract<ActionVerdict, { ok: false }>).message);
        return;
      }

      let next: HillstrikeState;
      try {
        next = applyAction(current, seat, action).state;
      } catch {
        setNotice("That action could not be played.");
        return;
      }

      const record = next.lastAction;
      if (!record) return;

      busyRef.current = true;
      setNotice(null);
      setAim(null);

      const flightMs = record.type === "shoot" ? flightDuration(record.impact.tick) : 0;
      setAnimation({
        action: record,
        from: current.battlefield,
        to: next.battlefield,
        startedAt: performance.now(),
        flightMs,
        settleMs: SETTLE_MS,
      });
      setResolving(true);

      timersRef.current.push(
        window.setTimeout(() => {
          installMatch(next);
        }, flightMs),
      );
      timersRef.current.push(
        window.setTimeout(() => {
          setAnimation(null);
          setResolving(false);
          busyRef.current = false;
        }, flightMs + SETTLE_MS),
      );
    },
    [installMatch],
  );

  const fire = useCallback(() => {
    if (!aim) return;
    playAction(HUMAN_SEAT, { type: "shoot", ...aim });
  }, [aim, playAction]);

  const drive = useCallback(
    (direction: MoveDirection) => {
      playAction(HUMAN_SEAT, { type: "move", direction });
    },
    [playAction],
  );

  // The bot answers on its own turn, after a short beat so its shot reads as a
  // turn rather than as the board moving by itself. It plans with the SAME
  // engine and the SAME projectile; difficulty only changes its aim search.
  useEffect(() => {
    if (!match || match.status !== "playing" || resolving) {
      setAiThinking(false);
      return;
    }
    if (match.turn !== AI_SEAT) {
      setAiThinking(false);
      return;
    }

    setAiThinking(true);
    const timer = window.setTimeout(() => {
      const current = matchRef.current;
      if (!current || current.status !== "playing" || current.turn !== AI_SEAT) {
        setAiThinking(false);
        return;
      }
      setAiThinking(false);
      try {
        const action = chooseAiAction({
          state: current,
          seat: AI_SEAT,
          difficulty,
        });
        playAction(AI_SEAT, action);
      } catch {
        setNotice("The bot could not find an action.");
      }
    }, AI_THINK_DELAY_MS);

    timersRef.current.push(timer);
    return () => window.clearTimeout(timer);
  }, [match, resolving, difficulty, playAction]);

  // Session tally, counted once per finished match.
  useEffect(() => {
    if (!match || match.status !== "finished") return;
    const key = `${match.seed}:${match.turnIndex}:${match.terminationReason ?? ""}`;
    if (countedMatchRef.current === key) return;
    countedMatchRef.current = key;
    if (match.winner === null) return;
    setSession((previous) =>
      match.winner === HUMAN_SEAT
        ? { ...previous, wins: previous.wins + 1 }
        : { ...previous, losses: previous.losses + 1 },
    );
  }, [match]);

  const matchOver = match?.status === "finished";

  if (!match) {
    return (
      <div className="min-h-screen overflow-x-clip bg-gradient-to-br from-[#001933] to-[#000d1a] px-3 pb-24 pt-20 text-white sm:px-6 md:pb-8">
        <NavigationBar currentPath={LOBBY_PATH} />
        <div
          data-testid="hillstrike-loading"
          className="mx-auto mt-10 max-w-md rounded-2xl border border-cyan-400/20 bg-black/40 p-6 text-center"
        >
          <p className="text-lg font-black uppercase tracking-[0.12em] text-[#7cefff]">
            Hillstrike
          </p>
          <p className="mt-1 text-sm text-white/60">Generating the battlefield…</p>
        </div>
      </div>
    );
  }

  const viewerHp = hpOf(match, HUMAN_SEAT);
  const botHp = hpOf(match, AI_SEAT);
  const outcome =
    match.winner === HUMAN_SEAT ? "win" : match.winner === null ? "draw" : "loss";

  return (
    <div className="min-h-screen overflow-x-clip bg-gradient-to-br from-[#001933] to-[#000d1a] text-white">
      <NavigationBar currentPath={LOBBY_PATH} />

      <div className="mx-auto flex max-w-[1800px] flex-col px-2 pb-6 pt-20 sm:px-3">
        <div className="mb-2 flex flex-wrap items-end justify-between gap-x-3 gap-y-1">
          <h1 className="logo-text text-lg font-black uppercase tracking-[0.12em] text-[#7cefff] drop-shadow-[0_0_16px_rgba(0,229,255,0.45)] sm:text-2xl">
            Hillstrike <span className="text-[#f5ff3b]">vs AI</span>
          </h1>
          <p className="text-[11px] text-white/55">
            Free practice · no wager · no rating · you are{" "}
            <span className="font-semibold text-cyan-300">cyan</span>, the bot is{" "}
            <span className="font-semibold text-pink-400">magenta</span>.
          </p>
        </div>

        {/* The game screen: the battlefield fills it, the controls sit inside it
            at the bottom, and neither ever needs a scroll to reach. */}
        <div className="flex h-[calc(100dvh-150px)] min-h-[400px] flex-col overflow-hidden rounded-2xl border border-cyan-400/25 bg-[#04101f] shadow-[0_0_30px_rgba(34,211,238,0.12)]">
          <div className="relative min-h-0 flex-1">
            <HillstrikeBattlefield
              state={match}
              viewerSeat={HUMAN_SEAT}
              preview={preview}
              aim={aim}
              animation={animation}
              interactive={canPlay}
              resolving={resolving}
              onAim={(shot) => {
                if (!canPlay) return;
                setAim(shot);
              }}
              onLock={(shot) => {
                if (!canPlay) return;
                setAim(shot);
              }}
              onClear={() => setAim(null)}
            />
          </div>

          <HillstrikeHud
            state={match}
            viewerSeat={HUMAN_SEAT}
            aiSeat={AI_SEAT}
            difficulty={difficulty}
            aim={aim}
            canPlay={canPlay}
            resolving={resolving}
            aiThinking={aiThinking}
            notice={notice}
            session={session}
            clockMs={clockMs}
            durationMs={durationMs}
            onDuration={changeDuration}
            onFire={fire}
            onClearAim={() => setAim(null)}
            onMove={drive}
            onRestart={restart}
          />
        </div>

        <AiDifficultyPicker
          gameKey="hillstrike"
          value={difficulty}
          onChange={setDifficulty}
          title="Bot difficulty"
          hint={HILLSTRIKE_TIER_HINTS}
          fallbackHint={HILLSTRIKE_TIER_HINTS[difficulty]}
        />

        <details className="mt-4 rounded-xl border border-white/10 bg-black/25 p-3 text-sm text-white/70">
          <summary className="cursor-pointer font-bold text-cyan-300">
            How to play Hillstrike
          </summary>
          <ol className="mt-2 list-decimal space-y-1.5 pl-5">
            <li>Drag away from your target on the battlefield to set direction and power, then press Fire.</li>
            <li>
              A turn is <strong>two actions</strong> (the opening turn is one). Each action is a shot
              or a drive.
            </li>
            <li>
              <strong>Drive</strong> closer or farther — up to {MOVE_RANGE} units from your spawn. The
              longer a shell flies, the weaker it hits, so closing the range is how you buy damage.
            </li>
            <li>
              A <strong>giant tower</strong> walls off the middle of the map from the ground to the sky:
              nothing crosses it, not even a lob over the top (that leaves the battlefield). Shoot a lane
              through its blocks to open a line on your opponent. Each block takes two hits, and nothing
              collapses into the hole you make.
            </li>
            <li>
              Your base has an <strong>indestructible roof</strong>, so you cannot be lobbed on from
              above at spawn — but the roof stays at spawn, and the hills around it are high. Drive out
              to fight.
            </li>
            <li>
              On each side of the tower sit <strong>three power-ups</strong> — double damage next shot,
              double blast next shot, or HP back. Drive over one to take it; each is dealt once, so no
              buff ever comes back.
            </li>
            <li>
              A direct hit costs HP in proportion to the flight distance (up to 50 at point blank,
              about 16 across the whole map). Ground and blocks never cost HP.
            </li>
            <li>
              {MAX_HP} HP each and a <strong>match clock</strong> (5, 10 or 15 minutes, your choice).
              The first tank knocked out to 0 loses immediately; when the clock runs out the tank with
              more HP wins, and level HP is a draw.
            </li>
            <li>Every match deals a new, mirrored layout: both seats always face identical ground, roofs and pickups.</li>
          </ol>
        </details>
      </div>

      <PvpResultScreen
        open={Boolean(matchOver)}
        outcome={outcome}
        headline={
          outcome === "win"
            ? "Tank knocked out — the hill is yours."
            : outcome === "draw"
              ? "Time — the hill stays unclaimed."
              : "The bot held the hill this time."
        }
        subline="Free practice — no wager, no rating, no trophies."
        gameName="Hillstrike vs AI"
        opponent={{ name: `AI (${difficulty})`, iconKey: null, isAi: true }}
        summary={[
          { label: "Your HP", value: String(viewerHp) },
          { label: "Bot HP", value: String(botHp) },
          { label: "Clock", value: `${durationMs / 60_000} min` },
          { label: "Actions taken", value: String(match.turnIndex) },
          { label: "Session", value: `${session.wins}W – ${session.losses}L` },
        ]}
        playAgain={{ label: "New layout", onClick: restart }}
        onReturnToLobby={() => router.push(LOBBY_PATH)}
      />
    </div>
  );
}
